<?php
use App\Models\AlumniPeserta;
use App\Services\AlumniWorkflowService;
use Livewire\Attributes\Computed; use Livewire\Attributes\Layout; use Livewire\Attributes\Title; use Livewire\Attributes\Url; use Livewire\Component; use Livewire\WithPagination;
new #[Layout('layouts.app'), Title('Publikasi Alumni')] class extends Component { use WithPagination; #[Url] public string $search=''; #[Url(as:'publikasi')] public string $publikasi='belum'; public ?int $selectedId=null; public string $platform=''; public string $urlPosting=''; public function mount():void{} public function updatedSearch():void{$this->resetPage();} public function updatedPublikasi():void{$this->resetPage();} #[Computed] public function participants(){return AlumniPeserta::query()->with(['activeVideo','publikasi'])->where('status_kurasi','lolos')->when($this->search,fn($q)=>$q->where(fn($nested)=>$nested->where('nama_lengkap','like','%'.$this->search.'%')->orWhereHas('activeVideo',fn($v)=>$v->where('original_name','like','%'.$this->search.'%'))))->when($this->publikasi,fn($q)=>$q->where('status_publikasi',$this->publikasi))->latest('registered_at')->paginate(12);} #[Computed] public function selected():?AlumniPeserta{return $this->selectedId?AlumniPeserta::query()->with(['activeVideo','publikasi'])->find($this->selectedId):null;} public function publish(AlumniWorkflowService $workflow):void{$this->validate(['selectedId'=>['required','exists:alumni_peserta,id'],'platform'=>['nullable','string','max:20'],'urlPosting'=>['nullable','url','max:2048']]);$workflow->publish(AlumniPeserta::findOrFail($this->selectedId),(int)auth()->id(),$this->platform?:null,$this->urlPosting?:null);$this->reset('selectedId','platform','urlPosting');$this->dispatch('toast',type:'success',message:'Karya dipublikasikan.');} public function unpublish(AlumniWorkflowService $workflow):void{$workflow->unpublish(AlumniPeserta::findOrFail($this->selectedId),(int)auth()->id());$this->reset('selectedId');$this->dispatch('toast',type:'success',message:'Publikasi dibatalkan.');} };
?>
