'sudah')<p class="text-sm">Dipublikasikan {{ $this->selected->publikasi?->dipublikasikan_at?->timezone('Asia/Jakarta')->format('d M Y H:i') }} WIB.</p>@if($this->selected->publikasi?->url_posting)<a class="mt-2 inline-block text-sm text-amber-700" target="_blank" href="{{ $this->selected->publikasi->url_posting }}">Buka tautan publik</a>@endif<flux:button class="mt-4" wire:click="unpublish" wire:confirm="Batalkan publikasi karya ini?" variant="danger">Batalkan publikasi</flux:button>@else<flux:input wire:model="platform" label="Platform (opsional)" placeholder="Instagram / TikTok"/><flux:input wire:model="urlPosting" class="mt-3" label="Tautan publik (opsional)" type="url"/><flux:button class="mt-4" wire:click="publish" wire:confirm="Publikasikan karya ini?" variant="primary">Publikasikan</flux:button>@endif</div></div></flux:card>@endif</div>
